16	package org.springframework.samples.petclinic.model;
17	
18	import java.time.LocalDate;
19	import java.time.Month;
20	
21	/**
22	 * The fiscal year a date falls in. Each fiscal year runs from 1 July to the following
23	 * 30 June and is named by the calendar year in which it ends, so 1 July 2025 through
24	 * 30 June 2026 is fiscal year 2026.
25	 */
26	public final class FiscalYear {
27	
28	    /** The month on whose first day each fiscal year begins. */
29	    private static final Month FISCAL_YEAR_START = Month.JULY;
30	
31	    private final int year;
32	
33	    private FiscalYear(int year) {
34	        this.year = year;
35	    }
36	
37	    /**
38	     * The fiscal year that {@code date} falls in: the date's calendar year on or after
39	     * 1 July, otherwise the previous calendar year (i.e. the year the fiscal year ends).
40	     */
41	    public static FiscalYear of(LocalDate date) {
42	        int calendarYear = date.getYear();
43	        int fiscalYear = date.getMonthValue() >= FISCAL_YEAR_START.getValue() ? calendarYear + 1 : calendarYear;
44	        return new FiscalYear(fiscalYear);
45	    }
46	
47	    /** The full fiscal year number, e.g. {@code 2026}. */
48	    public int getYear() {
49	        return this.year;
50	    }
51	
52	    /** The last two digits of the fiscal year, e.g. {@code 26}. */
53	    public int getShortYear() {
54	        return this.year % 100;
55	    }
56	
57	    /** The fiscal year formatted {@code FY<YY>} from its {@linkplain #getShortYear() two-digit year}, e.g. {@code FY26}. */
58	    public String getLabel() {
59	        return String.format("FY%02d", getShortYear());
60	    }
61	
62	    /** The number of whole fiscal years from this fiscal year up to {@code other} (0 within the same fiscal year). */
63	    public int yearsUntil(FiscalYear other) {
64	        return other.year - this.year;
65	    }
66	}
