16	package org.springframework.samples.petclinic.model;
17	
18	/**
19	 * Classification of an owner into a marketing segment formatted {@code <TIER>_<AREA>}. The tier is
20	 * {@code PREMIUM} for a membership level of {@value #PREMIUM_MIN_LEVEL} or more, otherwise
21	 * {@code STANDARD}; the area is {@code METRO} when the owner's locality is a known region, otherwise
22	 * {@code REGIONAL}.
23	 */
24	public final class OwnerSegment {
25	
26	    /** The membership level at or above which an owner is in the {@code PREMIUM} tier. */
27	    private static final int PREMIUM_MIN_LEVEL = 3;
28	
29	    private OwnerSegment() {
30	    }
31	
32	    /**
33	     * Return the segment for the given membership level and locality, formatted {@code <TIER>_<AREA>}.
34	     *
35	     * @param membershipLevel the owner's membership level
36	     * @param locality        the owner's locality (canonical region, or {@code UNKNOWN})
37	     * @return the segment string, one of {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL},
38	     *         {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}
39	     */
40	    public static String of(int membershipLevel, String locality) {
41	        return tier(membershipLevel) + "_" + area(locality);
42	    }
43	
44	    private static String tier(int membershipLevel) {
45	        return membershipLevel >= PREMIUM_MIN_LEVEL ? "PREMIUM" : "STANDARD";
46	    }
47	
48	    private static String area(String locality) {
49	        return LocalityResolver.isKnownRegion(locality) ? "METRO" : "REGIONAL";
50	    }
51	}
