317	    /**
318	     * Count the owners already stored whose registration date equals the given date. Used to
319	     * enforce the per-day registration limit at creation time.
320	     */
321	    @Override
322	    @Transactional(readOnly = true)
323	    public long countOwnersRegisteredOn(LocalDate registrationDate) throws DataAccessException {
324	        return ownerRepository.findAll().stream()
325	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
326	            .count();
327	    }
328	
329	    /**
330	     * Count the owners already stored that share the given first and last name, compared
331	     * case-insensitively. Used to capture an owner's namesake count at creation time.
332	     */
333	    private int countNamesakes(String firstName, String lastName) {
334	        return (int) ownerRepository.findAll().stream()
335	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
336	                && equalsIgnoreCase(existing.getLastName(), lastName))
337	            .count();
338	    }
