340	    /**
341	     * Ensure the given customer code does not collide with an already stored owner's. When it does,
342	     * append {@code -<n>} using the smallest {@code n} of 2 or more that makes it unique. Used to
343	     * guarantee that distinct owners always receive distinct customer codes at creation time.
344	     */
345	    private String deduplicateCustomerCode(String customerCode) {
346	        Set<String> existing = ownerRepository.findAll().stream()
347	            .map(Owner::getCustomerCode)
348	            .filter(code -> code != null)
349	            .collect(Collectors.toSet());
350	        if (!existing.contains(customerCode)) {
351	            return customerCode;
352	        }
353	        int suffix = 2;
354	        while (existing.contains(customerCode + "-" + suffix)) {
355	            suffix++;
356	        }
357	        return customerCode + "-" + suffix;
358	    }
359	
360	    private static boolean equalsIgnoreCase(String a, String b) {
361	        return a != null && a.equalsIgnoreCase(b);
362	    }
363	
364	    @Override
365	    @Transactional(readOnly = true)
366	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
367	        return ownerRepository.findByLastName(lastName);
368	    }
